def semver_sort(versions):
    def parse_version(version):
        # Split off build metadata
        if '+' in version:
            version_part, build = version.split('+', 1)
        else:
            version_part = version
            build = ""

        # Split core version and pre-release
        if '-' in version_part:
            core, prerelease = version_part.split('-', 1)
        else:
            core = version_part
            prerelease = ""

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0]) if len(parts) > 0 else 0
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_ids = []
        if prerelease:
            prerelease_ids = prerelease.split('.')

        return (major, minor, patch, prerelease_ids)

    def prerelease_key(ids):
        # A version with pre-release sorts before the same version without one
        # So we need: (has_prerelease, prerelease_comparison)
        # has_prerelease: False (no prerelease) sorts after True (has prerelease)
        # So use: (len(ids) == 0, ...) which makes (True, ...) > (False, ...)

        if len(ids) == 0:
            # No pre-release: sorts after any pre-release
            return (1,)

        # Has pre-release: convert to comparable form
        converted = []
        for identifier in ids:
            if identifier.isdigit():
                # All-digit identifiers: compare numerically, sort before non-digit
                converted.append((0, int(identifier)))
            else:
                # Non-digit identifiers: compare by ASCII order, sort after digit
                converted.append((1, identifier))

        return (0, tuple(converted))

    # Parse all versions with their original index for stable sort
    parsed = []
    for idx, version in enumerate(versions):
        major, minor, patch, prerelease_ids = parse_version(version)
        sort_key = (major, minor, patch, prerelease_key(prerelease_ids), idx)
        parsed.append((sort_key, version))

    # Sort by the key
    parsed.sort(key=lambda x: x[0])

    # Return sorted version strings
    return [version for _, version in parsed]

